import XCTest
import Foundation
import AVFoundation
import CoreVideo

final class FrameSequenceTests:XCTestCase {
    func samples(_ start:Int32,_ end:Int32,_ fps:Int)->[(frame:Int32,time:CMTime,progress:Float)] {var s=AvatarVideoFrameSequence(startFrame:start,endFrame:end,fps:fps)!;var values:[(frame:Int32,time:CMTime,progress:Float)]=[];while let value=s.next() {values.append(value)};return values}
    func testTwentyFourFpsKeepsOneSecondDuration() {let values=samples(0,24,24);XCTAssertEqual(values.map(\.frame),Array(0..<24).map(Int32.init));XCTAssertEqual(values[1].time.seconds,1.0/24,accuracy:0.000001);XCTAssertEqual(AvatarVideoFrameSequence(startFrame:0,endFrame:24,fps:24)!.duration.seconds,1)}
    func testSixtyFpsDownsamplesToThirty() {let values=samples(0,60,60);XCTAssertEqual(values.map(\.frame),stride(from:0,to:60,by:2).map(Int32.init));XCTAssertEqual(values[1].time.seconds,1.0/30,accuracy:0.000001);XCTAssertEqual(values.last?.progress,1)}
    func testNonzeroStartUsesRelativeTimeAndExclusiveEnd() {let values=samples(5,9,15);XCTAssertEqual(values.map(\.frame),[5,6,7,8]);XCTAssertEqual(values[0].time.seconds,0);XCTAssertEqual(AvatarVideoFrameSequence(startFrame:5,endFrame:9,fps:15)!.duration.seconds,4.0/15,accuracy:0.000001)}
    func testOddRateDoesNotSkipPastEnd() {let values=samples(0,59,59);XCTAssertEqual(values.count,30);XCTAssertEqual(values.first?.frame,0);XCTAssertEqual(values.last?.frame,57);XCTAssertTrue(zip(values,values.dropFirst()).allSatisfy {$0.frame < $1.frame && $0.time < $1.time})}
    func testSingleFrameHasPositiveDuration() {let values=samples(7,8,60);XCTAssertEqual(values.count,1);XCTAssertEqual(values[0].frame,7);XCTAssertEqual(values[0].time,.zero);XCTAssertEqual(AvatarVideoFrameSequence(startFrame:7,endFrame:8,fps:60)!.duration.seconds,1.0/60,accuracy:0.000001)}
    func testInvalidBoundsAndRatesRejected() {for (start,end,fps):(Int32,Int32,Int) in [(-1,5,30),(5,5,30),(6,5,30),(0,5,0),(0,5,-1),(0,5,Int.max)] {XCTAssertNil(AvatarVideoFrameSequence(startFrame:start,endFrame:end,fps:fps))}}
    func testExtremeValidRateDoesNotOverflow() {let values=samples(0,Int32.max,Int(Int32.max));XCTAssertEqual(values.count,30);XCTAssertLessThan(values.last!.frame,Int32.max);XCTAssertEqual(values.last!.progress,1)}
    func testRepeatedEndReturnsNil() {var s=AvatarVideoFrameSequence(startFrame:0,endFrame:1,fps:30)!;XCTAssertNotNil(s.next());XCTAssertNil(s.next());XCTAssertNil(s.next())}
}
final class NativeExportTests:XCTestCase {
    func buffer() throws ->CVPixelBuffer {var value:CVPixelBuffer?;let status=CVPixelBufferCreate(kCFAllocatorDefault,640,640,kCVPixelFormatType_32ARGB,nil,&value);XCTAssertEqual(status,kCVReturnSuccess);let buffer=try XCTUnwrap(value);CVPixelBufferLockBaseAddress(buffer,[]);if let address=CVPixelBufferGetBaseAddress(buffer) {memset(address,0,CVPixelBufferGetDataSize(buffer))};CVPixelBufferUnlockBaseAddress(buffer,[]);return buffer}
    func testRealH264ExportIsReadableAndPreservesDuration() throws {let export=try AvatarVideoExport(codec:AVVideoCodecType.h264.rawValue);let pixel=try buffer();let queue=DispatchQueue(label:"native-avatar-test");let done=expectation(description:"Encoded");var path:String?;var sequence=AvatarVideoFrameSequence(startFrame:0,endFrame:24,fps:24)!;queue.async {export.start(queue:queue,isCancelled:{false},next:{if let sample=sequence.next() {return .frame(pixel,sample.time)};return .finished(sequence.duration)},completed:{path=$0;done.fulfill()})};wait(for:[done],timeout:20);let output=try XCTUnwrap(path);defer {try? FileManager.default.removeItem(atPath:output)};let asset=AVURLAsset(url:URL(fileURLWithPath:output));XCTAssertEqual(asset.duration.seconds,1,accuracy:0.05);XCTAssertEqual(asset.tracks(withMediaType:.video).count,1);XCTAssertEqual(asset.tracks(withMediaType:.video).first?.naturalSize,CGSize(width:640,height:640))}
    func testRealWriterRejectsRenderFailure() throws {let export=try AvatarVideoExport(codec:AVVideoCodecType.h264.rawValue);let queue=DispatchQueue(label:"native-avatar-failure");let done=expectation(description:"Failed");queue.async {export.start(queue:queue,isCancelled:{false},next:{.failed},completed:{XCTAssertNil($0);done.fulfill()})};wait(for:[done],timeout:10)}
    func testCancellationBeforeStartDoesNotRender() throws {let export=try AvatarVideoExport(codec:AVVideoCodecType.h264.rawValue);let queue=DispatchQueue(label:"native-avatar-cancel");var rendered=0;var calls=0;queue.sync {export.start(queue:queue,isCancelled:{true},next:{rendered+=1;return .failed},completed:{XCTAssertNil($0);calls+=1})};XCTAssertEqual(rendered,0);XCTAssertEqual(calls,1)}
    func testRealCancellationDuringFrameProduction() throws {let export=try AvatarVideoExport(codec:AVVideoCodecType.h264.rawValue);let pixel=try buffer();let queue=DispatchQueue(label:"native-avatar-reentrant");let done=expectation(description:"Cancelled");queue.async {export.start(queue:queue,isCancelled:{false},next:{[weak export] in export?.cancel();return .frame(pixel,.zero)},completed:{XCTAssertNil($0);done.fulfill()})};wait(for:[done],timeout:10)}
}
